package com.example.discussions.dto;
import com.example.discussions.model.*;import java.time.Instant;import java.util.List;
public final class Responses {private Responses(){}public record Auth(String token,User user){}public record DiscussionView(Long id,String title,String body,String status,User author,Category category,long voteCount,long commentCount,boolean votedByMe,Instant createdAt,Instant updatedAt,List<Comment> comments){public static DiscussionView of(Discussion d,long votes,boolean mine){var roots=d.comments.stream().filter(c->c.parent==null).toList();return new DiscussionView(d.id,d.title,d.body,d.status.name(),d.author,d.category,votes,d.comments.size(),mine,d.createdAt,d.updatedAt,roots);}}public record Profile(Long id,String username,String displayName,String bio,String role,Instant createdAt,List<DiscussionView> discussions){} }
